        Unduh Template Audit Kamar
      </button>
<button class="px-space-md py-2 rounded-lg bg-primary text-on-primary hover:bg-primary-container font-label-md text-label-md shadow-sm transition-all" type="button">
        Buka Jadwal Pemeriksaan
      </button>
</div>
</div>
</div>
<script>
  // Active navigation helper for the App Shell context
  document.addEventListener('DOMContentLoaded', () => {
    const navItems = document.querySelectorAll('aside nav a');
    navItems.forEach(item => {
      if (item.getAttribute('data-path') === 'data-kamar') {
        item.classList.add('bg-primary-container', 'text-on-primary', 'font-label-lg', 'shadow-sm');
        item.classList.remove('text-on-surface-variant');
      }
    });
  });
</script>
<script src="/js/owner-shell.js"></script>
<!-- Modal Tambah/Ubah Kamar -->
<div id="roomModal" class="hidden fixed inset-0 z-50 bg-black/40 flex items-center justify-center p-4">
  <div class="bg-surface-container-lowest rounded-xl shadow-xl w-full max-w-lg max-h-[90vh] overflow-y-auto">
    <form id="roomForm" novalidate class="p-space-lg space-y-space-md">
      <div class="flex items-center justify-between">
        <h2 id="modalTitle" class="font-headline-md text-headline-md">Tambah Kamar</h2>
        <button type="button" id="btnCloseModal" class="p-1 rounded-lg text-outline hover:bg-surface-container-low"><span class="material-symbols-outlined">close</span></button>
      </div>
      <div id="roomFormError" class="hidden rounded-lg bg-error-container text-on-error-container font-body-sm text-body-sm px-3 py-2" role="alert"></div>
      <div class="grid grid-cols-2 gap-space-md">
        <div><label class="font-label-md text-label-md" for="f_room_number">No. Kamar</label>
          <input id="f_room_number" maxlength="10" class="mt-1 w-full px-3 py-2.5 rounded-lg bg-surface-container-low focus:outline-none focus:bg-white border border-transparent focus:border-primary" placeholder="mis. 105"/>
          <p class="hidden text-error font-body-sm text-body-sm" data-ferr="room_number"></p></div>
        <div><label class="font-label-md text-label-md" for="f_type">Tipe</label>
          <input id="f_type" list="typeList" maxlength="50" class="mt-1 w-full px-3 py-2.5 rounded-lg bg-surface-container-low focus:outline-none focus:bg-white border border-transparent focus:border-primary" placeholder="mis. Standar"/>
          <datalist id="typeList"></datalist>
          <p class="hidden text-error font-body-sm text-body-sm" data-ferr="type"></p></div>
      </div>
      <div class="grid grid-cols-2 gap-space-md">
        <div><label class="font-label-md text-label-md" for="f_price">Harga Sewa / bulan (Rp)</label>
          <input id="f_price" type="number" min="0" class="mt-1 w-full px-3 py-2.5 rounded-lg bg-surface-container-low focus:outline-none focus:bg-white border border-transparent focus:border-primary" placeholder="800000"/>
          <p class="hidden text-error font-body-sm text-body-sm" data-ferr="monthly_price"></p></div>
        <div><label class="font-label-md text-label-md" for="f_status">Status</label>
          <select id="f_status" class="mt-1 w-full px-3 py-2.5 rounded-lg bg-surface-container-low focus:outline-none border border-transparent focus:border-primary">
            <option value="kosong">Kosong (Siap Huni)</option>
            <option value="butuh_perbaikan">Butuh Perbaikan</option>
          </select>
          <p id="statusNote" class="hidden text-outline font-body-sm text-body-sm mt-1">Kamar terisi: status berubah otomatis saat penghuni check-out.</p>
          <p class="hidden text-error font-body-sm text-body-sm" data-ferr="status"></p></div>
      </div>
      <div><label class="font-label-md text-label-md" for="f_desc">Deskripsi (opsional)</label>
        <textarea id="f_desc" rows="2" maxlength="1000" class="mt-1 w-full px-3 py-2.5 rounded-lg bg-surface-container-low focus:outline-none focus:bg-white border border-transparent focus:border-primary"></textarea></div>
      <div><p class="font-label-md text-label-md mb-1">Fasilitas / item di kamar</p>
        <div id="itemsBox" class="grid grid-cols-1 sm:grid-cols-2 gap-2 max-h-48 overflow-y-auto rounded-lg bg-surface-container-low p-3 text-body-sm"></div>
        <p class="hidden text-error font-body-sm text-body-sm" data-ferr="items"></p></div>
      <div class="flex justify-end gap-space-sm pt-space-sm">
        <button type="button" id="btnCancel" class="px-space-md py-2 rounded-lg bg-surface-container-low hover:bg-surface-container font-label-md text-label-md">Batal</button>
        <button type="submit" id="btnSave" class="px-space-md py-2 rounded-lg bg-primary text-on-primary hover:bg-primary-container font-label-md text-label-md shadow-sm disabled:opacity-60">Simpan</button>
      </div>
    </form>
  </div>
</div>

<!-- Toast -->
<div id="toast" class="hidden fixed bottom-4 right-4 z-[60] px-4 py-3 rounded-lg shadow-lg font-label-md text-label-md"></div>

<script>
(() => {
  // ---------- Auth & helper API ----------
  const token = localStorage.getItem('kosaudit_token') || sessionStorage.getItem('kosaudit_token');
  if (!token) { window.location.href = '/login'; return; }

  async function api(path, opts = {}) {
    const res = await fetch('/api/owner' + path, {
      ...opts,
      headers: { 'Accept': 'application/json', 'Content-Type': 'application/json', 'Authorization': 'Bearer ' + token, ...(opts.headers || {}) },
    });
    const data = await res.json().catch(() => ({}));
    if (res.status === 401) { localStorage.removeItem('kosaudit_token'); sessionStorage.removeItem('kosaudit_token'); window.location.href = '/login'; throw new Error('unauthenticated'); }
    if (res.status === 403) { window.location.href = '/tenant/dashboard'; throw new Error('forbidden'); }
    if (!res.ok) { const e = new Error(data.message || 'Terjadi kesalahan.'); e.status = res.status; e.errors = data.errors || {}; throw e; }
    return data;
  }

  const $ = (id) => document.getElementById(id);
  const esc = (v) => String(v ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const rupiah = (n) => 'Rp ' + Number(n || 0).toLocaleString('id-ID');
  const STATUS = {
    kosong:          { label: 'Kosong',          cls: 'bg-secondary-fixed text-on-secondary-fixed-variant' },
    terisi:          { label: 'Terisi',          cls: 'bg-tertiary-fixed text-on-tertiary-fixed-variant' },
    butuh_perbaikan: { label: 'Butuh Perbaikan', cls: 'bg-error-container text-on-error-container' },
  };

  function toast(msg, ok = true) {
    const t = $('toast');
    t.textContent = msg;
    t.className = 'fixed bottom-4 right-4 z-[60] px-4 py-3 rounded-lg shadow-lg font-label-md text-label-md ' + (ok ? 'bg-tertiary-container text-on-tertiary-container' : 'bg-error text-on-error');
    setTimeout(() => t.classList.add('hidden'), 3000);
  }

  // ---------- State & render ----------
  let rooms = [];
  let masterItems = [];

  async function loadRooms() {
    try {
      const all = []; let page = 1, last = 1;
      do {
        const r = await api('/rooms?per_page=100&page=' + page);
        all.push(...r.data); last = r.meta?.last_page ?? 1; page++;
      } while (page <= last);
      rooms = all;
      render();
    } catch (e) {
      if (e.message === 'unauthenticated' || e.message === 'forbidden') return;
      $('roomsBody').innerHTML = '<tr><td colspan="7" class="py-10 text-center text-error">Gagal memuat data: ' + esc(e.message) + '</td></tr>';
    }
  }

  function render() {
    // statistik
    const total = rooms.length, occ = rooms.filter(r => r.status === 'terisi').length;
    $('statTotal').textContent = total; $('badgeTotal').textContent = total;
    $('statOccupied').textContent = occ;
    $('statAvailable').textContent = rooms.filter(r => r.status === 'kosong').length;
    $('statRepair').textContent = rooms.filter(r => r.status === 'butuh_perbaikan').length;
    $('statOccPct').textContent = total ? Math.round(occ / total * 100) : 0;

    // opsi filter tipe & status (dari data nyata)
    const types = [...new Set(rooms.map(r => r.type))].sort();
    const curType = $('filterType').value, curStatus = $('filterStatus').value, curFloor = $('filterFloor').value;
    $('filterType').innerHTML = '<option value="">Semua Tipe</option>' + types.map(t => '<option value="' + esc(t) + '">' + esc(t) + '</option>').join('');
    $('filterType').value = types.includes(curType) ? curType : '';
    $('filterStatus').innerHTML = '<option value="">Status (Semua)</option>' + Object.entries(STATUS).map(([v, o]) => '<option value="' + v + '">' + o.label + '</option>').join('');
    $('filterStatus').value = curStatus;
    const floors = [...new Set(rooms.map(r => String(r.room_number).charAt(0)).filter(c => /\d/.test(c)))].sort();
    $('filterFloor').innerHTML = '<option value="">Semua Lantai</option>' + floors.map(f => '<option value="' + f + '">Lantai ' + f + '</option>').join('');
    $('filterFloor').value = floors.includes(curFloor) ? curFloor : '';
    $('typeList').innerHTML = types.map(t => '<option value="' + esc(t) + '">').join('');

    // filter
    const q = $('searchRoom').value.trim().toLowerCase();
    const list = rooms.filter(r =>
      (!q || String(r.room_number).toLowerCase().includes(q) || String(r.type).toLowerCase().includes(q)) &&
      (!$('filterType').value || r.type === $('filterType').value) &&
      (!$('filterStatus').value || r.status === $('filterStatus').value) &&
      (!$('filterFloor').value || String(r.room_number).charAt(0) === $('filterFloor').value));

    if (!list.length) {
      $('roomsBody').innerHTML = '<tr><td colspan="7" class="py-10 text-center text-outline">' + (rooms.length ? 'Tidak ada kamar yang cocok dengan filter.' : 'Belum ada kamar. Klik "Tambah Kamar Baru" untuk memulai.') + '</td></tr>';
      return;
    }
    $('roomsBody').innerHTML = list.map(r => {
      const st = STATUS[r.status] || { label: r.status_label || r.status, cls: 'bg-surface-container-high text-on-surface' };
      return '<tr class="hover:bg-surface-container-low/60 transition-colors">' +
        '<td class="py-4 px-space-lg"><div class="flex items-center gap-space-sm"><div class="w-10 h-10 rounded-lg bg-surface-container-low flex items-center justify-center font-headline-sm text-headline-sm text-primary">' + esc(r.room_number) + '</div>' +
        '<div class="flex flex-col"><span class="font-label-lg text-label-lg">Kamar ' + esc(r.room_number) + '</span><span class="font-body-sm text-body-sm text-outline">Lantai ' + esc(String(r.room_number).charAt(0)) + '</span></div></div></td>' +
        '<td class="py-4 px-space-md">' + esc(r.type) + '</td>' +
        '<td class="py-4 px-space-md font-mono-numeric text-mono-numeric">' + rupiah(r.monthly_price) + '</td>' +
        '<td class="py-4 px-space-md">' + (r.master_items_count ?? 0) + ' item</td>' +
        '<td class="py-4 px-space-md text-outline">' + (r.status === 'terisi' ? 'Terisi' : '—') + '</td>' +
        '<td class="py-4 px-space-md text-center"><span class="px-2.5 py-1 rounded-full font-label-md text-label-md ' + st.cls + '">' + esc(st.label) + '</span></td>' +
        '<td class="py-4 px-space-lg"><div class="flex justify-end gap-1">' +
        '<button data-act="edit" data-id="' + r.id + '" class="p-1.5 rounded-lg text-outline hover:text-on-surface hover:bg-surface-container-low" title="Ubah"><span class="material-symbols-outlined text-[20px]">edit</span></button>' +
        '<button data-act="del" data-id="' + r.id + '" class="p-1.5 rounded-lg text-outline hover:text-error hover:bg-error-container/30" title="Hapus"><span class="material-symbols-outlined text-[20px]">delete</span></button>' +
        '</div></td></tr>';
    }).join('');
  }

  // sembunyikan pagination statis (semua data sudah dimuat)
  const pg = [...document.querySelectorAll('span')].find(x => x.textContent.trim() === 'Menampilkan');
  if (pg) { let el = pg.parentElement; while (el && !(el.textContent.includes('Sebelumnya') && el.textContent.includes('Berikutnya'))) el = el.parentElement; if (el) el.style.display = 'none'; }

  // ---------- Modal ----------
  let editingId = null;
  const modal = $('roomModal');

  function clearFormErrors() {
    $('roomFormError').classList.add('hidden');
    document.querySelectorAll('[data-ferr]').forEach(e => { e.textContent = ''; e.classList.add('hidden'); });
  }

  async function ensureMasterItems() {
    if (masterItems.length) return;
    const r = await api('/master-items?all=1');
    masterItems = r.data;
  }

  function renderItems(selected = {}) {
    $('itemsBox').innerHTML = masterItems.length ? masterItems.map(m => {
      const on = selected[m.id] !== undefined;
      return '<label class="flex items-center gap-2"><input type="checkbox" class="accent-primary" data-item="' + m.id + '" ' + (on ? 'checked' : '') + '/>' +
        '<span class="flex-1">' + esc(m.name) + '</span>' +
        '<input type="number" min="1" max="255" value="' + (selected[m.id] ?? 1) + '" data-qty="' + m.id + '" class="w-14 px-1 py-0.5 rounded bg-white border border-outline-variant text-center"/></label>';
    }).join('') : '<span class="text-outline">Belum ada master item.</span>';
  }

  async function openModal(room = null) {
    clearFormErrors();
    editingId = room ? room.id : null;
    $('modalTitle').textContent = room ? 'Ubah Kamar ' + room.room_number : 'Tambah Kamar';
    $('f_room_number').value = room?.room_number ?? '';
    $('f_type').value = room?.type ?? '';
    $('f_price').value = room?.monthly_price ?? '';
    $('f_desc').value = room?.description ?? '';
    const occupied = room?.status === 'terisi';
    $('f_status').value = occupied ? 'kosong' : (room?.status ?? 'kosong');
    $('f_status').disabled = occupied;
    $('statusNote').classList.toggle('hidden', !occupied);
    modal.classList.remove('hidden');
    try {
      await ensureMasterItems();
      let selected = {};
      if (room) {
        const d = await api('/rooms/' + room.id);
        (d.data.master_items || []).forEach(m => { selected[m.id] = m.quantity ?? 1; });
      }
      renderItems(selected);
    } catch (e) { toast(e.message, false); }
  }
  function closeModal() { modal.classList.add('hidden'); }

  $('btnAddRoom').addEventListener('click', () => openModal());
  $('btnCloseModal').addEventListener('click', closeModal);
  $('btnCancel').addEventListener('click', closeModal);
  modal.addEventListener('click', (e) => { if (e.target === modal) closeModal(); });

  $('roomForm').addEventListener('submit', async (e) => {
    e.preventDefault();
    clearFormErrors();
    const items = [...document.querySelectorAll('[data-item]:checked')].map(cb => ({
      master_item_id: Number(cb.dataset.item),
      quantity: Number(document.querySelector('[data-qty="' + cb.dataset.item + '"]').value) || 1,
    }));
    const body = {
      room_number: $('f_room_number').value.trim(),
      type: $('f_type').value.trim(),
      monthly_price: $('f_price').value === '' ? null : Number($('f_price').value),
      description: $('f_desc').value.trim() || null,
      items,
    };
    if (!$('f_status').disabled) body.status = $('f_status').value;

    $('btnSave').disabled = true;
    try {
      await api(editingId ? '/rooms/' + editingId : '/rooms', { method: editingId ? 'PUT' : 'POST', body: JSON.stringify(body) });
      closeModal();
      toast(editingId ? 'Kamar berhasil diperbarui.' : 'Kamar berhasil ditambahkan.');
      await loadRooms();
    } catch (err) {
      if (err.status === 422) {
        const left = [];
        Object.entries(err.errors).forEach(([k, msgs]) => {
          const key = k.startsWith('items') ? 'items' : k;
          const el = document.querySelector('[data-ferr="' + key + '"]');
          if (el) { el.textContent = msgs[0]; el.classList.remove('hidden'); } else left.push(msgs[0]);
        });
        if (left.length) { $('roomFormError').textContent = left.join(' '); $('roomFormError').classList.remove('hidden'); }
      } else if (err.message !== 'unauthenticated' && err.message !== 'forbidden') {
        $('roomFormError').textContent = err.message; $('roomFormError').classList.remove('hidden');
      }
    } finally { $('btnSave').disabled = false; }
  });

  // ---------- Edit / hapus dari tabel ----------
  $('roomsBody').addEventListener('click', async (e) => {
    const b = e.target.closest('button[data-act]'); if (!b) return;
    const room = rooms.find(r => String(r.id) === b.dataset.id); if (!room) return;
    if (b.dataset.act === 'edit') return openModal(room);
    if (b.dataset.act === 'del') {
      if (!confirm('Hapus Kamar ' + room.room_number + '?')) return;
      try { await api('/rooms/' + room.id, { method: 'DELETE' }); toast('Kamar berhasil dihapus.'); await loadRooms(); }
      catch (err) { toast(err.message, false); }
    }
  });

  ['searchRoom', 'filterType', 'filterStatus', 'filterFloor'].forEach(id => $(id).addEventListener('input', render));
  loadRooms();
})();
</script>
</main></div></body></html>
